  "imgThumb": "assets/figuras/docx/b2-tema-7-8-9-biologia-celular/image48.thumb.webp",
  "imageDesc": null,
  "q": "<b>40.- En relación con la imagen adjunta, conteste a las siguientes cuestiones:</b><br>a) ¿Qué tipo de transporte de membrana representa la imagen en su conjunto? [0,2]<br>b) ¿Qué procesos específicos se representan con las letras A, B y C? [0,3]<br>c) ¿Cómo se denominan los orgánulos, estructuras o moléculas representadas con los números del 1 al 5? [0,5]",
  "c": [
   "a) Endocitosis",
   "b) A: fagocitosis; B: pinocitosis; C: endocitosis mediada por receptor",
   "c) 1: pseudópodos; 2: vesícula fagocítica o fagosoma; 3: vesícula pinocítica; 4: vesícula endocítica; 5: receptor de membrana"
  ],
  "f": "Pregunta y figura transcritas de «B2.TEMA 7-8-9. BIOLOGÍA CELULAR.docx». La solución mostrada es la del propio documento.",
