  "q": "<b>23. En relación con la figura adjunta, conteste a las siguientes cuestiones:</b><br>a) ¿Qué proceso biológico se representa en la figura? [0,2]<br>b) Identifique a qué corresponde cada número del 1 al 8 [0,8].",
